def blocks(g):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out={}
    for r in range(R):
        for c in range(C):
            if g[r][c] and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<R and 0<=nx<C and g[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                rs=[y for y,x in cells]; cs=[x for y,x in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                out[(r0,r1,c0,c1)]=g[(r0+r1)//2][(c0+c1)//2]
    return out
