                        if 0<=ny<R and 0<=nx<C and g[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                rs=[y for y,x in cells]; cs=[x for y,x in cells]
                cr,cc=(min(rs)+max(rs))//2,(min(cs)+max(cs))//2
                v=g[cr][cc]
                inner=[(y,x) for y,x in cells if g[y][x]==v]
                inners[v].append(inner)
    for v,groups in inners.items():
        if len(groups)!=4: continue
